# Purpose: Keep experiment-report transformations and plot delivery out of the Rmd.
# Input: RDS result objects generated by 02-ablation-experiment.R.
# Parameters: Display k and technical columns selected by the Rmd.
# Output: Tidy tables for figures and evidence-anchored prose.

.ae_ablation_params <- function(filtered_cohorts, n_cores) {
  list(
    comparison = list(
      module_ids = NULL,
      direct_group = "Direct-GSClassifier",
      cohort_group = "Cohort-d1"
    ),
    provenance = list(
      external_cohorts = filtered_cohorts,
      max_reference_samples = Inf,
      max_query_samples = Inf,
      require_external = TRUE
    ),
    anchors = list(
      primary = "cancer_type",
      primary_role = "independent",
      bank_aligned = "tissue",
      technical = c("assay_type", "platform_id", "source_system"),
      min_reference_cohorts = 2L
    ),
    geometry = list(
      k = c(5L, 15L, 30L),
      search = "annoy",
      n_trees = 75L,
      search_k = 10000L,
      exact_validation_queries = 30L,
      min_annoy_recall = 0.90,
      geometry_samples = 5000L,
      distance_pairs = 100000L
    ),
    validation = list(
      enabled = TRUE,
      learning_fractions = c(0.10, 0.25, 0.50, 1.00),
      repeats = 10L,
      inner_folds = 3L,
      lambda = c(0.1, 1, 10),
      nrounds = 30L,
      min_class_n = 20L,
      numCores = n_cores
    ),
    scaling = list(
      enabled = TRUE,
      module_counts = c(10L, 25L, 50L, 75L, 100L, 125L, 150L),
      sequences = 5L,
      direct_feature_type = "all",
      sensitivity_feature_type = "gene_pair",
      biology_anchors = character(),
      score_reference_samples = 5000L,
      score_query_samples = 2000L,
      lambda = 1,
      bootstrap = 2000L
    ),
    controls = list(
      null_rp = TRUE,
      null_rp_rank = 100L,
      null_rp_seeds = 20260805L + seq_len(3L),
      null_perm = TRUE
    ),
    tradeoffs = list(
      decoder = TRUE,
      decoder_rank = 50L,
      decoder_lambda = 1,
      decoder_max_reference_samples = 10000L,
      decoder_max_query_samples = 5000L
    ),
    output = list(
      cover = TRUE,
      cache_external_d1 = TRUE
    )
  )
}

.ae_metric_long <- function(data, id_columns, metric_columns) {
  parts <- lapply(metric_columns, function(metric) {
    result <- data[, id_columns, drop = FALSE]
    result$metric <- metric
    result$value <- data[[metric]]
    result
  })
  do.call(rbind, parts)
}

.ae_retrieval_cohort_delta <- function(retrieval, k) {
  data <- retrieval$paired[retrieval$paired$k == k, , drop = FALSE]
  .ae_metric_long(
    data,
    id_columns = c("sample_id", "cohort", "label", "k"),
    metric_columns = c(
      "delta_top_k_label_rate",
      "delta_mrr",
      "delta_top1_label_match"
    )
  ) |>
    dplyr::group_by(.data$cohort, .data$metric) |>
    dplyr::summarise(
      estimate = mean(.data$value, na.rm = TRUE),
      sample_count = dplyr::n(),
      .groups = "drop"
    )
}

.ae_technical_delta <- function(retrieval, k, technical_columns) {
  data <- retrieval$per_sample[
    retrieval$per_sample$k == k,
    ,
    drop = FALSE
  ]
  keys <- c("sample_id", "cohort", "label", "k")
  direct <- data[data$representation == "Direct-GSClassifier", , drop = FALSE]
  d1 <- data[data$representation == "Cohort-d1", , drop = FALSE]
  paired <- merge(d1, direct, by = keys, suffixes = c("_d1", "_direct"))
  parts <- lapply(technical_columns, function(column) {
    metric <- paste0(column, "_match_excess")
    d1_name <- paste0(metric, "_d1")
    direct_name <- paste0(metric, "_direct")
    if (!all(c(d1_name, direct_name) %in% colnames(paired))) {
      return(NULL)
    }
    data.frame(
      sample_id = paired$sample_id,
      cohort = paired$cohort,
      technical_factor = column,
      delta_excess = paired[[d1_name]] - paired[[direct_name]],
      stringsAsFactors = FALSE
    )
  })
  parts <- parts[!vapply(parts, is.null, logical(1))]
  data <- do.call(rbind, parts)
  data |>
    dplyr::group_by(.data$cohort, .data$technical_factor) |>
    dplyr::summarise(
      estimate = mean(.data$delta_excess, na.rm = TRUE),
      sample_count = dplyr::n(),
      .groups = "drop"
    )
}

.ae_learning_summary <- function(curve) {
  curve$metrics |>
    dplyr::group_by(.data$representation, .data$requested_fraction) |>
    dplyr::summarise(
      estimate = mean(.data$balanced_accuracy, na.rm = TRUE),
      se = stats::sd(.data$balanced_accuracy, na.rm = TRUE) /
        sqrt(sum(is.finite(.data$balanced_accuracy))),
      min = min(.data$balanced_accuracy, na.rm = TRUE),
      max = max(.data$balanced_accuracy, na.rm = TRUE),
      .groups = "drop"
    )
}

.ae_top_abs <- function(data, value, n = 3L) {
  data[order(abs(data[[value]]), decreasing = TRUE), , drop = FALSE] |>
    utils::head(n)
}

.ae_resolve_module_labels <- function(module_ids, resolution_audit) {
  bank_tissue <- sub("[|].*$", "", module_ids)
  cohort <- sub("^[^|]*[|]", "", module_ids)
  mapped_tissue <- resolution_audit$resolved_tissue[
    match(cohort, resolution_audit$cohort)
  ]
  display_tissue <- ifelse(
    bank_tissue == "Undefined" & !is.na(mapped_tissue),
    mapped_tissue,
    bank_tissue
  )
  paste(display_tissue, cohort, sep = "|")
}

.ae_find_source_line <- function(path, pattern) {
  lines <- readLines(path, warn = FALSE)
  match(TRUE, grepl(pattern, lines, fixed = TRUE))
}

.ae_save_plot <- function(plot, file_stem, figure_dir, preview_dir, figure_params, dpi) {
  pdf_path <- file.path(figure_dir, paste0(file_stem, ".pdf"))
  jpg_path <- file.path(preview_dir, paste0(file_stem, ".jpg"))
  ggplot2::ggsave(
    filename = pdf_path,
    plot = plot,
    width = figure_params$width_in,
    height = figure_params$height_in,
    device = grDevices::cairo_pdf
  )
  bensz_pdf_to_jpg(pdf_path, jpg_path, dpi = dpi)
}

# Cohort-level inference helpers -------------------------------------------------
# All resampling is performed on complete clusters, then the same sampled
# clusters are used for both representations through their paired delta.
.ae_paired_inference <- function(
  data,
  delta_column,
  cluster_column = "cohort",
  n_boot = 2000L,
  seed = 20260829L,
  unit = "cohort",
  method = "cluster_bootstrap_sign_flip",
  alternative = "two.sided",
  null = 0,
  multiplicity_method = "none",
  min_clusters = 2L
) {
  required <- c(delta_column, cluster_column)
  if (!all(required %in% names(data))) {
    return(data.frame(
      estimate = NA_real_, ci_low = NA_real_, ci_high = NA_real_,
      p_value = NA_real_, p_value_adj = NA_real_, n_cohort = 0L,
      n_sample = 0L, resamples = 0L, seed = as.integer(seed), unit = unit,
      method = method, alternative = alternative, null = null,
      multiplicity_method = multiplicity_method, status = "not_estimable",
      reason = "missing_required_columns", stringsAsFactors = FALSE
    ))
  }

  keep <- is.finite(data[[delta_column]]) & !is.na(data[[cluster_column]])
  observed <- data[keep, required, drop = FALSE]
  if (nrow(observed) == 0L) {
    return(data.frame(
      estimate = NA_real_, ci_low = NA_real_, ci_high = NA_real_,
      p_value = NA_real_, p_value_adj = NA_real_, n_cohort = 0L,
      n_sample = 0L, resamples = 0L, seed = as.integer(seed), unit = unit,
      method = method, alternative = alternative, null = null,
      multiplicity_method = multiplicity_method, status = "not_estimable",
      reason = "no_finite_pairs", stringsAsFactors = FALSE
    ))
  }

  cluster_values <- split(observed[[delta_column]], observed[[cluster_column]])
  cluster_values <- cluster_values[vapply(cluster_values, length, integer(1)) > 0L]
  n_cluster <- length(cluster_values)
  cluster_means <- vapply(cluster_values, mean, numeric(1), na.rm = TRUE)
  estimate <- mean(cluster_means)
  base <- data.frame(
    estimate = estimate, ci_low = NA_real_, ci_high = NA_real_,
    p_value = NA_real_, p_value_adj = NA_real_, n_cohort = n_cluster,
    n_sample = nrow(observed), resamples = as.integer(max(0L, n_boot)),
    seed = as.integer(seed), unit = unit, method = method,
    alternative = alternative, null = null,
    multiplicity_method = multiplicity_method, status = "complete",
    reason = "", stringsAsFactors = FALSE
  )
  if (n_cluster < as.integer(min_clusters)) {
    base$status <- "not_estimable"
    base$reason <- if (min_clusters > 2L) {
      paste0("fewer_than_", min_clusters, "_independent_clusters")
    } else {
      "fewer_than_two_independent_clusters"
    }
    return(base)
  }

  n_boot <- as.integer(n_boot)
  if (is.na(n_boot) || n_boot < 100L) {
    base$status <- "not_estimable"
    base$reason <- "bootstrap_repeats_below_minimum"
    return(base)
  }

  old_seed <- if (exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE)) {
    get(".Random.seed", envir = .GlobalEnv)
  } else NULL
  on.exit({
    if (is.null(old_seed)) {
      if (exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE)) {
        rm(".Random.seed", envir = .GlobalEnv)
      }
    } else {
      assign(".Random.seed", old_seed, envir = .GlobalEnv)
    }
  }, add = TRUE)
  set.seed(seed)
  bootstrap <- replicate(
    n_boot,
    mean(sample(cluster_means, n_cluster, replace = TRUE)),
    simplify = TRUE
  )
  base$ci_low <- unname(stats::quantile(bootstrap, 0.025, names = FALSE, type = 6))
  base$ci_high <- unname(stats::quantile(bootstrap, 0.975, names = FALSE, type = 6))

  # Exact sign-flip for small cluster counts; Monte Carlo otherwise.
  if (n_cluster <= 16L) {
    signs <- as.matrix(expand.grid(rep(list(c(-1, 1)), n_cluster)))
    null_distribution <- apply(signs, 1L, function(s) mean(s * (cluster_means - null)))
  } else {
    null_distribution <- replicate(
      n_boot,
      mean(sample(c(-1, 1), n_cluster, replace = TRUE) * (cluster_means - null)),
      simplify = TRUE
    )
  }
  exceed <- sum(abs(null_distribution) >= abs(estimate - null))
  base$p_value <- (exceed + 1) / (length(null_distribution) + 1)
  base
}

.ae_adjust_inference <- function(inference, method = "holm") {
  if (!"p_value" %in% names(inference)) return(inference)
  inference$p_value_adj <- NA_real_
  ok <- is.finite(inference$p_value)
  if (any(ok)) inference$p_value_adj[ok] <- stats::p.adjust(inference$p_value[ok], method = method)
  inference$multiplicity_method <- method
  inference
}

.ae_retrieval_inference <- function(
  retrieval, k = 30L, n_boot = 2000L, seed = 20260829L,
  multiplicity_method = "holm"
) {
  paired <- retrieval$paired[retrieval$paired$k == k, , drop = FALSE]
  metrics <- c(
    top_k_label_rate = "delta_top_k_label_rate",
    mrr = "delta_mrr",
    top1_label_match = "delta_top1_label_match"
  )
  rows <- lapply(seq_along(metrics), function(i) {
    out <- .ae_paired_inference(
      paired, metrics[[i]], cluster_column = "cohort", n_boot = n_boot,
      seed = seed + i - 1L, unit = "cohort", method = "cohort_bootstrap_sign_flip",
      multiplicity_method = multiplicity_method
    )
    out$endpoint <- names(metrics)[i]
    out$k <- k
    out
  })
  result <- do.call(rbind, rows)
  result <- .ae_adjust_inference(result, multiplicity_method)
  result[order(match(result$endpoint, names(metrics))), , drop = FALSE]
}

.ae_readout_inference <- function(
  readout, n_boot = 2000L, seed = 20260829L,
  multiplicity_method = "holm"
) {
  paired <- readout$paired_by_cohort
  metrics <- c(
    balanced_accuracy = "delta_balanced_accuracy",
    macro_auroc = "delta_macro_auroc"
  )
  rows <- lapply(seq_along(metrics), function(i) {
    out <- .ae_paired_inference(
      paired, metrics[[i]], cluster_column = "cohort", n_boot = n_boot,
      seed = seed + i - 1L, unit = "query", method = "query_cohort_bootstrap_sign_flip",
      multiplicity_method = multiplicity_method
    )
    if (all(c("sample_count_d1", "sample_count_direct") %in% names(paired))) {
      out$n_sample <- sum(
        pmax(paired$sample_count_d1, paired$sample_count_direct),
        na.rm = TRUE
      )
    }
    out$endpoint <- names(metrics)[i]
    out
  })
  result <- do.call(rbind, rows)
  .ae_adjust_inference(result, multiplicity_method)
}

.ae_learning_inference <- function(
  curve, n_boot = 2000L, seed = 20260829L,
  multiplicity_method = "holm"
) {
  fractions <- sort(unique(curve$paired$requested_fraction))
  rows <- lapply(seq_along(fractions), function(i) {
    part <- curve$paired[curve$paired$requested_fraction == fractions[i], , drop = FALSE]
    out <- .ae_paired_inference(
      part, "delta_balanced_accuracy", cluster_column = "repeat_id",
      n_boot = n_boot, seed = seed + i - 1L, unit = "design_repeat",
      method = "paired_design_repeat_bootstrap_sign_flip",
      multiplicity_method = multiplicity_method,
      min_clusters = 10L
    )
    out$requested_fraction <- fractions[i]
    out$primary <- fractions[i] == max(fractions)
    out
  })
  result <- do.call(rbind, rows)
  .ae_adjust_inference(result, multiplicity_method)
}
